import type { WorkflowRuleFormType } from "./types";

export const WORKFLOW_TRIGGER_OPTIONS = [
  { label: "Order Created (when customer places order)", value: "order_created" },
  { label: "Order Paid (when payment is captured)", value: "order_paid" },
  { label: "Customer Created (when new signup)", value: "customer_created" },
  { label: "Inventory Low (when stock < threshold)", value: "inventory_low" },
  { label: "Refund Issued (when refund processed)", value: "refund_issued" },
];

export const CONDITION_FIELD_OPTIONS = [
  { label: "Order Total ($)", value: "order.total_price" },
  { label: "Customer Tags", value: "customer.tags" },
  { label: "Customer Order Count", value: "customer.orders_count" },
  { label: "Shipping Country Code", value: "shipping.country_code" },
  { label: "Payment Gateway", value: "payment.gateway" },
];

export const CONDITION_OPERATOR_OPTIONS = [
  { label: "is greater than", value: "greater_than" },
  { label: "is less than", value: "less_than" },
  { label: "equals exactly", value: "equals" },
  { label: "contains keyword", value: "contains" },
  { label: "is not equal to", value: "is_not" },
];

export const ACTION_TYPE_OPTIONS = [
  { label: "Add Customer Tag", value: "add_customer_tag" },
  { label: "Send Automated Merchant Email", value: "send_email" },
  { label: "Post Alert to Slack Webhook", value: "send_slack" },
  { label: "Generate Customer Loyalty Discount", value: "apply_discount" },
];

export const INITIAL_WORKFLOW_FORM: WorkflowRuleFormType = {
  name: "Auto-Tag High-Value VIP Orders",
  description: "When an order exceeds $150, apply VIP tag and alert support channel.",
  enabled: true,
  triggerEvent: "order_created",
  logicGate: "AND",
  conditions: [
    {
      id: "cond-1",
      field: "order.total_price",
      operator: "greater_than",
      value: "150",
    },
    {
      id: "cond-2",
      field: "shipping.country_code",
      operator: "equals",
      value: "US",
    },
  ],
  actions: [
    {
      id: "act-1",
      actionKey: "add_customer_tag",
      actionLabel: "Add Customer Tag",
      targetValue: "VIP-Gold",
    },
    {
      id: "act-2",
      actionKey: "send_slack",
      actionLabel: "Post Alert to Slack Webhook",
      targetValue: "#vip-sales-feed",
    },
  ],
  totalRuns: 1420,
  lastRunAt: "2 minutes ago",
};

import * as React from "react";
import {
  Page,
  BlockStack,
  Banner,
  SaveBar,
} from "@xco-agency/corex-ui";
import { INITIAL_WORKFLOW_FORM } from "../constants";
import { WorkflowTriggerCard } from "../partials/WorkflowTriggerCard";
import { WorkflowConditionsCard } from "../partials/WorkflowConditionsCard";
import { WorkflowActionsCard } from "../partials/WorkflowActionsCard";
import { WorkflowStatusSidebarCard } from "../partials/WorkflowStatusSidebarCard";
import type {
  WorkflowActionType,
  WorkflowConditionItemType,
  WorkflowRuleFormType,
  WorkflowTriggerEventType,
} from "../types";

export function WorkflowBuilderExample() {
  const [form, setForm] = React.useState<WorkflowRuleFormType>(INITIAL_WORKFLOW_FORM);
  const [isDirty, setIsDirty] = React.useState(false);
  const [isSaving, setIsSaving] = React.useState(false);
  const [notification, setNotification] = React.useState<string | null>(null);

  const updateField = <K extends keyof WorkflowRuleFormType>(
    field: K,
    val: WorkflowRuleFormType[K],
  ) => {
    setForm((prev) => ({ ...prev, [field]: val }));
    setIsDirty(true);
  };

  const handleUpdateCondition = (
    id: string,
    updates: Partial<WorkflowConditionItemType>,
  ) => {
    const next = form.conditions.map((c) => (c.id === id ? { ...c, ...updates } : c));
    updateField("conditions", next);
  };

  const handleAddCondition = () => {
    const newCond: WorkflowConditionItemType = {
      id: `cond-${Date.now()}`,
      field: "customer.orders_count",
      operator: "greater_than",
      value: "3",
    };
    updateField("conditions", [...form.conditions, newCond]);
  };

  const handleRemoveCondition = (id: string) => {
    updateField(
      "conditions",
      form.conditions.filter((c) => c.id !== id),
    );
  };

  const handleUpdateAction = (id: string, updates: Partial<WorkflowActionType>) => {
    const next = form.actions.map((a) => (a.id === id ? { ...a, ...updates } : a));
    updateField("actions", next);
  };

  const handleAddAction = () => {
    const newAction: WorkflowActionType = {
      id: `act-${Date.now()}`,
      actionKey: "send_email",
      actionLabel: "Send Automated Merchant Email",
      targetValue: "admin@store.com",
    };
    updateField("actions", [...form.actions, newAction]);
  };

  const handleRemoveAction = (id: string) => {
    updateField(
      "actions",
      form.actions.filter((a) => a.id !== id),
    );
  };

  const handleSave = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      setIsDirty(false);
      setNotification("Automation workflow deployed and active!");
    }, 500);
  };

  const handleDiscard = () => {
    setForm(INITIAL_WORKFLOW_FORM);
    setIsDirty(false);
  };

  const handleSimulateRun = () => {
    setNotification("Dry run passed: All 2 conditions matched. 2 simulated actions succeeded.");
  };

  return (
    <Page
      heading="Automation Workflow Builder"
      subheading="Construct trigger-condition-action flows to automate customer tags, alerts, and store logic."
      inlineSize="large"
    >
      <BlockStack gap="base">
        {notification && (
          <Banner
            tone="success"
            title={notification}
            onDismiss={() => setNotification(null)}
          />
        )}

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "minmax(0, 2fr) minmax(280px, 1fr)",
            gap: "var(--p-space-400, 16px)",
            alignItems: "start",
          }}
        >
          {/* Main Column */}
          <BlockStack gap="base">
            <WorkflowTriggerCard
              name={form.name}
              description={form.description}
              triggerEvent={form.triggerEvent}
              onUpdateName={(val) => updateField("name", val)}
              onUpdateDescription={(val) => updateField("description", val)}
              onUpdateTrigger={(val: WorkflowTriggerEventType) =>
                updateField("triggerEvent", val)
              }
            />

            <WorkflowConditionsCard
              logicGate={form.logicGate}
              conditions={form.conditions}
              onUpdateLogicGate={(gate) => updateField("logicGate", gate)}
              onUpdateCondition={handleUpdateCondition}
              onAddCondition={handleAddCondition}
              onRemoveCondition={handleRemoveCondition}
            />

            <WorkflowActionsCard
              actions={form.actions}
              onUpdateAction={handleUpdateAction}
              onAddAction={handleAddAction}
              onRemoveAction={handleRemoveAction}
            />
          </BlockStack>

          {/* Sidebar Column */}
          <WorkflowStatusSidebarCard
            enabled={form.enabled}
            totalRuns={form.totalRuns}
            lastRunAt={form.lastRunAt}
            conditionCount={form.conditions.length}
            actionCount={form.actions.length}
            onToggleEnabled={(enabled) => updateField("enabled", enabled)}
            onSimulateRun={handleSimulateRun}
          />
        </div>

        {isDirty && (
          <SaveBar
            open={isDirty}
            onSave={handleSave}
            onDiscard={handleDiscard}
            loading={isSaving}
          />
        )}
      </BlockStack>
    </Page>
  );
}

export { WorkflowBuilderExample } from "./examples/WorkflowBuilderExample";
export type {
  WorkflowActionType,
  WorkflowConditionItemType,
  WorkflowConditionOperatorType,
  WorkflowRuleFormType,
  WorkflowTriggerEventType,
} from "./types";

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Select,
  TextField,
  Box,
  Divider,
} from "@xco-agency/corex-ui";
import { ACTION_TYPE_OPTIONS } from "../constants";
import type { WorkflowActionType } from "../types";

type WorkflowActionsCardPropsType = {
  actions: WorkflowActionType[];
  onUpdateAction: (id: string, updates: Partial<WorkflowActionType>) => void;
  onAddAction: () => void;
  onRemoveAction: (id: string) => void;
};

export function WorkflowActionsCard({
  actions,
  onUpdateAction,
  onAddAction,
  onRemoveAction,
}: WorkflowActionsCardPropsType) {
  return (
    <Card>
      <BlockStack gap="base">
        <InlineStack justifyContent="space-between" alignItems="center">
          <BlockStack gap="small-400">
            <InlineStack gap="small-200" alignItems="center">
              <Badge tone="info">Step 3</Badge>
              <Text as="h3" fontWeight="semibold">
                Actions: Then perform these steps
              </Text>
            </InlineStack>
            <Text color="subdued" variant="bodySm">
              Sequential operations executed automatically when conditions pass.
            </Text>
          </BlockStack>
          <Badge tone="success">{actions.length} Actions in Sequence</Badge>
        </InlineStack>

        <Divider />

        <BlockStack gap="small-200">
          {actions.map((act, index) => (
            <Box
              key={act.id}
              padding="small"
              background="base"
              borderRadius="base"
              borderWidth="small-100"
              borderColor="subdued"
              borderStyle="solid"
            >
              <InlineStack gap="base" alignItems="center" justifyContent="space-between">
                <Box inlineSize="70px">
                  <Badge tone="info">THEN {index + 1}</Badge>
                </Box>

                <div style={{ flex: 1 }}>
                  <Select
                    label="Action Type"
                    value={act.actionKey}
                    options={ACTION_TYPE_OPTIONS}
                    onChange={(val) => {
                      const found = ACTION_TYPE_OPTIONS.find((o) => o.value === val);
                      onUpdateAction(act.id, {
                        actionKey: val as WorkflowActionType["actionKey"],
                        actionLabel: found?.label ?? val,
                      });
                    }}
                  />
                </div>

                <div style={{ flex: 1 }}>
                  <TextField
                    label="Parameter / Target Value"
                    value={act.targetValue}
                    onChange={(val) => onUpdateAction(act.id, { targetValue: val })}
                    placeholder="e.g. VIP-Gold or #channel-name"
                  />
                </div>

                <Button
                  variant="plain"
                  tone="critical"
                  icon="delete"
                  disabled={actions.length <= 1}
                  onClick={() => onRemoveAction(act.id)}
                >
                  Remove
                </Button>
              </InlineStack>
            </Box>
          ))}

          <InlineStack justifyContent="flex-start">
            <Button variant="secondary" icon="plus" onClick={onAddAction}>
              Add Automated Action Step
            </Button>
          </InlineStack>
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Select,
  TextField,
  Box,
  Divider,
} from "@xco-agency/corex-ui";
import {
  CONDITION_FIELD_OPTIONS,
  CONDITION_OPERATOR_OPTIONS,
} from "../constants";
import type {
  WorkflowConditionItemType,
  WorkflowConditionOperatorType,
} from "../types";

type WorkflowConditionsCardPropsType = {
  logicGate: "AND" | "OR";
  conditions: WorkflowConditionItemType[];
  onUpdateLogicGate: (gate: "AND" | "OR") => void;
  onUpdateCondition: (
    id: string,
    updates: Partial<WorkflowConditionItemType>,
  ) => void;
  onAddCondition: () => void;
  onRemoveCondition: (id: string) => void;
};

export function WorkflowConditionsCard({
  logicGate,
  conditions,
  onUpdateLogicGate,
  onUpdateCondition,
  onAddCondition,
  onRemoveCondition,
}: WorkflowConditionsCardPropsType) {
  return (
    <Card>
      <BlockStack gap="base">
        <InlineStack justifyContent="space-between" alignItems="center">
          <BlockStack gap="small-400">
            <InlineStack gap="small-200" alignItems="center">
              <Badge tone="info">Step 2</Badge>
              <Text as="h3" fontWeight="semibold">
                Conditions: Check if these rules match
              </Text>
            </InlineStack>
            <Text color="subdued" variant="bodySm">
              Only execute subsequent actions if incoming trigger matches this criteria.
            </Text>
          </BlockStack>

          <InlineStack gap="small-200" alignItems="center">
            <Text variant="bodySm" color="subdued">
              Match:
            </Text>
            <Button
              variant={logicGate === "AND" ? "primary" : "secondary"}
              onClick={() => onUpdateLogicGate("AND")}
            >
              ALL (AND)
            </Button>
            <Button
              variant={logicGate === "OR" ? "primary" : "secondary"}
              onClick={() => onUpdateLogicGate("OR")}
            >
              ANY (OR)
            </Button>
          </InlineStack>
        </InlineStack>

        <Divider />

        <BlockStack gap="small-200">
          {conditions.map((cond, idx) => (
            <Box
              key={cond.id}
              padding="small"
              background="base"
              borderRadius="base"
              borderWidth="small-100"
              borderColor="subdued"
              borderStyle="solid"
            >
              <InlineStack gap="base" alignItems="center" justifyContent="space-between">
                <Box inlineSize="60px">
                  <Badge tone="neutral">
                    {idx === 0 ? "IF" : logicGate}
                  </Badge>
                </Box>

                <div style={{ flex: 1 }}>
                  <Select
                    label="Field Property"
                    value={cond.field}
                    options={CONDITION_FIELD_OPTIONS}
                    onChange={(val) => onUpdateCondition(cond.id, { field: val })}
                  />
                </div>

                <div style={{ flex: 1 }}>
                  <Select
                    label="Operator"
                    value={cond.operator}
                    options={CONDITION_OPERATOR_OPTIONS}
                    onChange={(val) =>
                      onUpdateCondition(cond.id, {
                        operator: val as WorkflowConditionOperatorType,
                      })
                    }
                  />
                </div>

                <div style={{ flex: 1 }}>
                  <TextField
                    label="Value"
                    value={cond.value}
                    onChange={(val) => onUpdateCondition(cond.id, { value: val })}
                  />
                </div>

                <Button
                  variant="plain"
                  tone="critical"
                  icon="delete"
                  disabled={conditions.length <= 1}
                  onClick={() => onRemoveCondition(cond.id)}
                >
                  Remove
                </Button>
              </InlineStack>
            </Box>
          ))}

          <InlineStack justifyContent="flex-start">
            <Button variant="secondary" icon="plus" onClick={onAddCondition}>
              Add Rule Condition
            </Button>
          </InlineStack>
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Select,
  TextField,
  Box,
} from "@xco-agency/corex-ui";
import { WORKFLOW_TRIGGER_OPTIONS } from "../constants";
import type { WorkflowTriggerEventType } from "../types";

type WorkflowTriggerCardPropsType = {
  name: string;
  description: string;
  triggerEvent: WorkflowTriggerEventType;
  onUpdateName: (name: string) => void;
  onUpdateDescription: (description: string) => void;
  onUpdateTrigger: (trigger: WorkflowTriggerEventType) => void;
};

export function WorkflowTriggerCard({
  name,
  description,
  triggerEvent,
  onUpdateName,
  onUpdateDescription,
  onUpdateTrigger,
}: WorkflowTriggerCardPropsType) {
  return (
    <Card>
      <BlockStack gap="base">
        <InlineStack justifyContent="space-between" alignItems="center">
          <BlockStack gap="small-400">
            <InlineStack gap="small-200" alignItems="center">
              <Badge tone="info">Step 1</Badge>
              <Text as="h3" fontWeight="semibold">
                Trigger: When this happens
              </Text>
            </InlineStack>
            <Text color="subdued" variant="bodySm">
              Define the initiating event in Shopify that fires this automation.
            </Text>
          </BlockStack>
        </InlineStack>

        <TextField
          label="Workflow Name"
          value={name}
          onChange={onUpdateName}
          placeholder="e.g. Auto-Tag High-Value VIP Orders"
        />

        <TextField
          label="Description (Optional)"
          value={description}
          onChange={onUpdateDescription}
          placeholder="Summary of what this automation accomplishes"
        />

        <Box
          padding="base"
          background="subdued"
          borderRadius="base"
          borderWidth="small-100"
          borderColor="subdued"
          borderStyle="solid"
        >
          <BlockStack gap="small-200">
            <Select
              label="Select Shopify Trigger Event"
              value={triggerEvent}
              options={WORKFLOW_TRIGGER_OPTIONS}
              onChange={(val) => onUpdateTrigger(val as WorkflowTriggerEventType)}
            />
            <Text color="subdued" variant="bodySm">
              Payload includes line items, customer address, tags, and gateway details.
            </Text>
          </BlockStack>
        </Box>
      </BlockStack>
    </Card>
  );
}

export type WorkflowTriggerEventType =
  | "order_created"
  | "order_paid"
  | "customer_created"
  | "inventory_low"
  | "refund_issued";

export type WorkflowConditionOperatorType =
  | "greater_than"
  | "less_than"
  | "equals"
  | "contains"
  | "is_not";

export type WorkflowConditionItemType = {
  id: string;
  field: string;
  operator: WorkflowConditionOperatorType;
  value: string;
};

export type WorkflowActionType = {
  id: string;
  actionKey: "add_customer_tag" | "send_email" | "send_slack" | "apply_discount";
  actionLabel: string;
  targetValue: string;
};

export type WorkflowRuleFormType = {
  name: string;
  description: string;
  enabled: boolean;
  triggerEvent: WorkflowTriggerEventType;
  logicGate: "AND" | "OR";
  conditions: WorkflowConditionItemType[];
  actions: WorkflowActionType[];
  totalRuns: number;
  lastRunAt: string;
};
